const items = $input.all();
const item = items[0];

let output = item.output || item.json?.output || item.json?.text || '';
output = output.replace(/```json|```/g, '').trim();

// Extrai titulo e legenda diretamente por regex — evita problema de JSON malformado
const tituloMatch = output.match(/"titulo"\s*:\s*"([\s\S]*?)(?<!\\)",/);
const legendaMatch = output.match(/"legenda"\s*:\s*"([\s\S]*?)(?<!\\)"[\s\n]*}/);

if (!tituloMatch || !legendaMatch) {
  throw new Error('❌ Não foi possível extrair titulo/legenda. Raw: ' + output.substring(0, 500));
}

let titulo = tituloMatch[1]
  .replace(/\\"/g, '"')
  .replace(/\\n/g, '\n');

let legenda = legendaMatch[1]
  .replace(/\\"/g, '"')
  .replace(/\\n/g, '\n');

const sanitizar = (str) => str.replace(/[—–]/g, (match, offset, string) => {
  const antes = string[offset - 1] || '';
  const depois = string[offset + 1] || '';
  if (antes === '\n' || depois === '\n') return '';
  return ', ';
}).replace(/[ \t]{2,}/g, ' ').trim();

titulo = sanitizar(titulo);
legenda = sanitizar(legenda);

const ts = Date.now().toString(36).toUpperCase();
const rand = Math.floor(Math.random() * 99999).toString(36).toUpperCase().padStart(3, '0');
const raw = (ts + rand).replace(/[^A-Z0-9]/g, '');
const uniqueId = raw.slice(-8).padStart(8, '0');

return [{
  json: {
    titulo,
    legenda,
    unique_id: uniqueId,
    video_url_s3: $('Video Extractor').first().json.video_url,
    video_original_s3_key: $('Video Extractor').first().json.original_url,
    video_clean_path: $('Video CROP').first().json.video_url
  }
}];

